-- The database is the last line of defence against double booking: one staff
-- member cannot have two active appointments with overlapping blocked ranges.
ALTER TABLE "appointments"
  ADD CONSTRAINT "appointments_no_overlap_excl"
  EXCLUDE USING gist (
    "tenant_id" WITH =,
    "staff_member_id" WITH =,
    tstzrange("blocked_from", "blocked_until", '[)') WITH &&
  ) WHERE ("status" IN ('HELD', 'CONFIRMED'));
